    const visibleRoleKeys = editableRoleKeys.includes(user.role) ? editableRoleKeys : [user.role, ...editableRoleKeys];
    visibleRoleKeys.forEach((key) => role.append(option(key, roleName(key))));
    role.value = user.role;
