  modal.append(head, makeField("날짜", `${key}ManualDateV66`, date), makeField("제목", `${key}ManualTitleV66`, title), makeField("내용", `${key}ManualMemoV66`, memo), makeField("원문 링크", `${key}ManualLinkV66`, link), save);
