    const confirmedRow = { id, ...(confirmed.data() || {}) };
    const rows = examGradeRowsV138(kind); const index = rows.findIndex((item) => String(item.id) === id);
    if (index >= 0) rows[index] = confirmedRow; else rows.unshift(confirmedRow);
